using System.Text;
using System.Security.Cryptography;
using System.Text.Json;
using ReviveOS.Core;
namespace ReviveOS.Browser;
public record ShortcutRecord(string Path,string Target,string Arguments,string? Hash);
public static class ChromeShortcut {
 static string Journal=>Path.Combine(State.Root,"chrome-shortcut.json");
 static string Command(ShortcutRecord r)=>"$d=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('"+Convert.ToBase64String(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(r)))+"'))|ConvertFrom-Json; $w=New-Object -ComObject WScript.Shell; ";
 public static async Task Create(){var exe=ChromeRuntime.FindChrome()??throw new IOException("Chrome não encontrado");var path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Chrome leve ReviveOS.lnk");if(File.Exists(path))throw new IOException("Atalho já existe; não foi sobrescrito");if(File.Exists(Journal))throw new IOException("Há registro de atalho anterior; restaure antes de criar outro");var args="--user-data-dir=\""+ChromeRuntime.LightProfile+"\" --new-window chrome://newtab/";var r=new ShortcutRecord(path,exe,args,null);State.Save(Journal,r);await Commands.CheckedPowerShell(Command(r)+"$s=$w.CreateShortcut($d.Path);$s.TargetPath=$d.Target;$s.Arguments=$d.Arguments;$s.Description='Perfil Chrome separado; perfil original preservado';$s.Save(); if(!(Test-Path -LiteralPath $d.Path)){throw 'Atalho não criado'}; $s=$w.CreateShortcut($d.Path); if($s.TargetPath -ne $d.Target -or $s.Arguments -ne $d.Arguments){throw 'Validação de atalho falhou'}");r=r with{Hash=Convert.ToHexString(SHA256.HashData(await File.ReadAllBytesAsync(path)))};State.Save(Journal,r);}
 public static async Task Restore(){if(!File.Exists(Journal))return;var r=JsonSerializer.Deserialize<ShortcutRecord>(await File.ReadAllTextAsync(Journal))??throw new IOException("Registro de atalho inválido");var expected=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Chrome leve ReviveOS.lnk");if(!string.Equals(r.Path,expected,StringComparison.OrdinalIgnoreCase))throw new IOException("Destino do atalho não reconhecido");if(File.Exists(r.Path)){if(r.Hash!=null&&Convert.ToHexString(SHA256.HashData(await File.ReadAllBytesAsync(r.Path)))!=r.Hash)throw new IOException("Atalho foi alterado; preservado para não remover mudanças do usuário");await Commands.CheckedPowerShell(Command(r)+"$s=$w.CreateShortcut($d.Path); if($s.TargetPath -ne $d.Target -or $s.Arguments -ne $d.Arguments){throw 'Atalho divergente; preservado'}");File.Delete(r.Path);}File.Delete(Journal);}
}
